import json,html
from pathlib import Path
p=Path(__file__).resolve().parents[1]
q=json.loads((p/'docs/corretivo/quantidades-original-pesquisadas.json').read_text())
a=json.loads((p/'curadoria/business/pesquisa-artigos-corretivo.json').read_text())
v=json.loads((p/'curadoria/business/pesquisa-videos-literatura-corretivo.json').read_text())
ac=[json.loads(f.read_text()) for f in (p/'src/content/business/acervo').glob('*.json')]
pub=[x for x in ac if x['status']=='publicado']; urls={x['url'].rstrip('/') for x in pub}
novos=[x for x in a['itens'] if x['url'].rstrip('/') not in urls]
e=html.escape
def link(url,label): return f'<a href="{e(url,quote=True)}" target="_blank" rel="noopener noreferrer">{e(str(label))} ↗</a>'
def texto(t): return e(str(t or 'Não confirmado'))
rows=[('Vídeos',155,0,'24 candidatos; 10 h 05 min 45 s nominais; nenhuma revisão integral concluída.'),('Referências: artigos e relatórios',63,6,f'28 candidatos; 4 já constam no acervo e {len(novos)} URLs são novas. Cobertura potencial: 30 referências; ainda faltariam 33 para o volume original.'),('Livros',58,8,'8 fichas existentes conferidas; não são 8 livros adicionais. Faltam 50 indicações para equivalência de volume.'),('Notícias',23,0,'13 matérias ativam a segunda página do arquivo; 23 reproduzem o volume publicado.'),('Estudos',12,0,'Há 8 guias curtos existentes. Não foram aceitos como 12 estudos com profundidade equivalente.'),('Análises',1,0,'Uma análise completa é reutilizada no card lateral e no destaque editorial.'),('Começando',4,0,'4 textos ilustrados no original, embora a série anuncie 10. Guias atuais ainda não equivalem ao formato desta série.'),('Dossiês de aprendizado',10,0,'Produção temática com contexto, mecanismo, exemplos, limites e referências.'),('Seções de equações/métodos',16,6,'6 explicações curtas de métricas existentes; diagramação matemática e aprofundamento ainda em migração.'),('Termos do glossário',14,8,'8 definições existentes. Metas de quantidade não autorizam inventar termos ou fatos.'),('Pautas visíveis',5,5,'5 propostas autorais preparadas no adaptador, claramente distintas de discussões reais.')]
table=''.join(f'<tr><th scope="row">{e(n)}</th><td>{orig}</td><td>{at}</td><td>{e(note)}</td></tr>' for n,orig,at,note in rows)
slots=''.join(f'<tr><th scope="row">{e(s["id"].replace("_"," "))}</th><td>{s["quantity"]}</td><td>{e(s["interpretation"])}</td></tr>' for s in q['slots'] if s['id'].startswith('home_') or s['id'] in ['radar_lateral','noticias_destaques','noticias_arquivo_pagina'])
articles=''
for x in a['itens']:
 autores='; '.join(x['autores']) if isinstance(x.get('autores'),list) else x.get('autores')
 articles+=f'''<article class="candidate" data-kind="artigo"><div class="label">{texto(x['id'])} · {texto(x['fonte'])} · {texto(x['natureza'])}</div><h3>{link(x['url'],x['titulo'])}</h3><p>{texto(autores)} · {texto(x.get('data_publicacao'))} · {texto(x['idioma'])}</p><p><b>Temas:</b> {e(', '.join(x['tema']))}</p><p><b>Consulta realizada:</b> {texto(x['consultado'])}</p><p><b>Acesso:</b> {texto(x['acesso'])}</p><p><b>Limites:</b> {texto(x['limites'])}</p><span class="state">Candidato · revisão integral pendente{' · já existe no acervo' if x['url'].rstrip('/') in urls else ''}</span></article>'''
vids=''
for x in v['videos']:
 dur=x['duracao_segundos']; mm,ss=divmod(dur,60)
 vids+=f'''<article class="candidate" data-kind="video"><div class="label">{texto(x['canal']['nome'])} · {texto(x['nivel_proposto'])} · {mm} min {ss:02d} s</div><h3>{link(x['url'],x['titulo_oficial'])}</h3><p>{texto(x['tema'])} · publicação: {texto(x['data_publicacao_youtube'][:10])}</p><p><b>Especialistas:</b> {texto(x['especialistas'])}</p><p><b>Canal confirmado:</b> {link(x['canal']['url'],x['canal']['channel_id_confirmado'])}</p><p><b>Idioma proposto:</b> {texto(x['idioma']['proposto'])}; audição integral pendente.</p><details><summary>Evidências e pendências</summary><ul>{''.join(f'<li>{link(t["url"],t["url"])}</li>' for t in x['evidencias_primarias'])}</ul><p>{e(' '.join(x['revisao']['pendencias']))}</p><p>{e(' '.join(x['ressalvas']))}</p></details><span class="state">Metadados verificados · conteúdo integral não revisado</span></article>'''
books=''
for x in v['literatura']:
 trad=x['traducao_portugues']
 books+=f'''<article class="candidate" data-kind="livro"><div class="label">Edição {texto(x['edicao_confirmada'])} · ISBN {texto(x['isbn_aprovado'])}</div><h3>{link(x['url_editorial'],x['titulo'])}</h3><p>{texto(x['autores'])}</p><p><b>Formato deste ISBN:</b> {texto(x['formato_do_isbn'])}</p><p><b>Português:</b> {texto(trad['status'])}</p>{f'<p>{link(trad["url"],"Catálogo da tradução")}</p>' if trad.get('url') else ''}<p><b>Capa:</b> {texto(x['capa']['estado'])}. Correspondência visual e condições de republicação pendentes.</p><span class="state">Conferência bibliográfica · leitura integral não declarada</span></article>'''
report=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Harpya Business — pesquisa de quantidade e acervo corretivo</title><style>
:root{{--ink:#282d33;--muted:#58636c;--gold:#8a6214;--line:#d9dfe3;--bg:#f8f9fa}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 system-ui,sans-serif}}header,main,footer{{max-width:1280px;margin:auto;padding:32px 28px}}header{{border-bottom:3px solid #c79a39;padding-top:50px}}header p{{max-width:90ch}}h1{{font-size:clamp(28px,4vw,46px);line-height:1.15;letter-spacing:-.04em;max-width:920px}}h2{{font-size:27px;line-height:1.3;margin:0 0 18px}}h3{{font-size:18px;line-height:1.4;margin:10px 0}}p{{margin:10px 0}}a{{color:var(--gold);text-underline-offset:3px;overflow-wrap:anywhere}}nav{{display:flex;flex-wrap:wrap;gap:12px 22px;margin-top:24px}}section{{margin:20px 0 55px;scroll-margin-top:20px}}.eyebrow,.label{{font-size:12px;font-weight:700;color:var(--gold);letter-spacing:.07em;text-transform:uppercase}}.notice{{border-left:4px solid #c79a39;background:#fff8e8;padding:18px 22px;margin:25px 0}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:26px 0}}.stats div{{background:white;padding:18px;border:1px solid var(--line)}}.stats b{{display:block;font-size:30px}}.stats small{{color:var(--muted)}}.table-wrap{{overflow-x:auto}}table{{width:100%;border-collapse:collapse;background:white;text-align:left;font-size:14px}}th,td{{border-bottom:1px solid var(--line);padding:13px;vertical-align:top}}thead{{background:#282d33;color:white}}tbody th{{min-width:170px}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}}.candidate{{border:1px solid var(--line);padding:22px;background:white;border-radius:8px;min-width:0}}.candidate p{{font-size:14px}}.state{{display:block;font-size:12px;font-weight:650;border-top:1px solid var(--line);padding-top:12px;margin-top:15px;color:#5f561e}}details{{font-size:13px;margin-top:14px}}summary{{cursor:pointer;font-weight:650}}.filter{{display:flex;gap:12px;align-items:center;margin:20px 0}}input{{padding:12px;font:inherit;border:1px solid #aeb8bf;border-radius:4px;flex:1;max-width:620px}}[hidden]{{display:none!important}}footer{{font-size:13px;border-top:1px solid var(--line)}}code{{overflow-wrap:anywhere;font-size:12px}}@media(max-width:740px){{.grid{{grid-template-columns:1fr}}.stats{{grid-template-columns:1fr 1fr}}header,main,footer{{padding:24px 18px}}th,td{{padding:10px}}}}
</style></head><body><header><div class="eyebrow">Pesquisa concluída · execução corretiva em andamento · 06/11/2026</div><h1>Quanto conteúdo é necessário para reconstruir o Harpya Business?</h1><p>A referência é o código do Harpya Tecnologia e Matemática, commit <code>939e5f75d0bb7b0fc8028471a20c31b353204ba0</code>. A contagem abaixo considera o que os leitores realmente publicam, as posições dos componentes e as funções que dependem de quantidade.</p><div class="stats"><div><b>28</b><small>candidatos a artigos/relatórios</small></div><div><b>24</b><small>candidatos a vídeos reais</small></div><div><b>8</b><small>livros existentes conferidos</small></div><div><b>10,10 h</b><small>duração nominal dos vídeos</small></div></div><nav><a href="#quantidades">Quantidades</a><a href="#slots">Posições da interface</a><a href="#producao">Ordem de produção</a><a href="#artigos">28 artigos</a><a href="#videos">24 vídeos</a><a href="#livros">8 livros</a><a href="#execucao">Execução</a></nav></header><main>
<section id="quantidades"><h2>Volume original, acervo atual e diferença</h2><div class="notice"><b>Volume e diagramação são critérios diferentes.</b> Usar o mesmo template não transforma 8 livros em um acervo equivalente a 58. Reutilizar uma notícia no carrossel, na grade e na página da matéria não cria três conteúdos. As metas de volume abaixo são derivadas do original; não são autorização para inventar evidências, autores, datas ou textos.</div><div class="table-wrap"><table><thead><tr><th>Família</th><th>Original publicado</th><th>Business existente / preparado</th><th>Leitura da diferença</th></tr></thead><tbody>{table}</tbody></table></div><p>Origens exige outra unidade de produção: o original tem <b>4 eras, 5 capítulos, 34 eventos, 12 personagens e 11 retratos locais</b>. Cada marco Business precisará de fonte histórica, contexto, referências e recurso visual adequado. Não há cronologia Business equivalente pronta.</p><p>Os 155 vídeos correspondem a 54 iniciantes, 58 intermediários e 43 avançados em 13 módulos. A pesquisa inicial propõe 8 iniciantes, 10 intermediários e 6 avançados; nenhuma classificação substitui revisão integral. Se todos os 24 forem aceitos, ainda faltarão 131 vídeos para o volume de referência.</p></section>
<section id="slots"><h2>Posições que precisam ser preenchidas e testadas</h2><div class="table-wrap"><table><thead><tr><th>Componente original</th><th>Quantidade</th><th>Como contar</th></tr></thead><tbody>{slots}</tbody></table></div><p>Para testar a paginação são necessárias <b>13 notícias</b>; 24 preenchem duas páginas completas, enquanto o original publica 23. Para preencher o radar da home são necessários <b>10 itens elegíveis</b>: um destaque e nove cards. A lateral possui três grupos de até duas leituras. As leituras podem ser reutilizadas entre componentes quando cumprem seus critérios.</p><p>A série Começando anuncia 10 artigos, mas possui 4 publicados. A análise anuncia 2 partes, mas possui 1 publicada. Há 32 arquivos de pautas, dos quais apenas 5 passam pelo filtro de exibição. Rascunhos ficam fora da contagem.</p></section>
<section id="producao"><h2>Produção necessária, sem inflar as quantidades</h2><ol><li><b>Estrutura:</b> compartilhar componentes originais, menus, barras, imagens, grade, filtros, índices, carrosséis, paginação e comportamento responsivo.</li><li><b>Conteúdo inicial para testar os recursos:</b> 12 estudos, 4 artigos ilustrados de Começando, 1 análise, 13 notícias, 5 pautas propostas, 6 referências bibliográficas, 8 livros, 10 itens de radar e distribuição de vídeos suficiente para os três níveis e todos os módulos escolhidos. A proposta intermediária de 13 módulos × 3 níveis resulta em 39 vídeos; os 24 candidatos atuais ainda não a atendem.</li><li><b>Profundidade temática:</b> dossiês de aprendizado, métricas com equações e pressupostos, glossário, cronologia, biografias, créditos e referências. Quantidades históricas são parâmetros de profundidade; não quotas para criar fórmulas ou marcos artificiais.</li><li><b>Acervo equivalente ao original:</b> completar e revisar 155 vídeos, 63 referências, 58 livros e 23 notícias. A cobertura inicial não será apresentada como equivalência integral.</li><li><b>Revisão e validação:</b> leitura/audição integral dos materiais selecionados, alegações rastreáveis, resumos próprios, contexto brasileiro, acesso/idioma, contraste entre caso, correlação e causa, revisão visual comparativa e teste dos recursos.</li></ol><p><b>Esforço medido dos vídeos:</b> 36.345 segundos, ou 10 h 05 min 45 s. Uma reprodução completa a 1× consome esse tempo; anotações, conferência de referências, redação, edição e testes são trabalho adicional ainda não medido. A duração desta amostra não permite estimar com precisão o tempo dos 155 vídeos.</p><p><b>Imagens:</b> reutilizar os recursos de marca, os três recortes ilustrativos dos estudos e os SVGs do sistema original. O original possui 56 capas de livros e 2 alternativas gráficas próprias, 14 SVGs nos quatro artigos Começando e 11 retratos em Origens. As capas localizadas na pesquisa ainda precisam de correspondência da edição e verificação de uso. Miniaturas dos vídeos devem derivar dos IDs reais.</p></section>
<div class="filter"><label for="busca">Filtrar pesquisa</label><input id="busca" type="search" placeholder="Instituição, autor, título ou tema"><span id="contador" aria-live="polite">60 fichas</span></div>
<section id="artigos"><h2>28 candidatos a artigos e relatórios</h2><p>16 fontes editoriais representadas; 7 itens brasileiros. Inclui 6 papers principais e 1 de reserva. Há 4 duplicações com o acervo já publicado: são 24 URLs novas, não 28 novos registros. Páginas, PDFs ou metadados primários consultados estão discriminados em cada ficha. Revisão integral concluída: zero.</p><div class="grid">{articles}</div></section>
<section id="videos"><h2>24 candidatos de 8 canais institucionais</h2><p>Channel ID individual, data, duração e credenciais foram conferidos nas fontes primárias. Idioma, nível e adequação pedagógica são propostas até a revisão integral. São 7 vídeos brasileiros e 17 candidatos em inglês. Coach, anúncio de curso e autoridade sem comprovação não constituem material curricular.</p><div class="grid">{vids}</div></section>
<section id="livros"><h2>8 obras iniciais conferidas</h2><p>Estas obras já integram a seleção inicial. ISBNs identificam formatos específicos: um ISBN de eBook não pode ser apresentado como ISBN impresso. Tradução, edição e capa precisam corresponder à mesma obra cadastrada.</p><div class="grid">{books}</div></section>
<section id="execucao"><h2>Execução iniciada e limites desta entrega</h2><p>A correção está no branch local <code>codex/harpya-business-corretivo</code>, em checkout isolado. Home, biblioteca, catálogo de vídeos, radar lateral, textos, fichas de leitura, índice de análises, notícias, comunidade e catálogo de fontes receberam componentes compartilhados do original. O menu Business agora deriva da ordem, visibilidade e ícones do menu original. Os estilos globais azuis que alteravam cabeçalho e botões foram retirados.</p><p>Esta é uma etapa da execução, com Astro check sem erros, build de 99 páginas, 43 testes Node e 13 testes Python aprovados. A comparação do conteúdo principal de 12 rotas técnicas preservou elementos, textos e atributos, normalizando apenas identificadores gerados e nomes de arquivos CSS. Essa evidência de regressão não substitui o aceite visual e editorial de Business. Outras famílias de páginas e a produção editorial completa continuam pendentes. Candidatos permanecem na pesquisa; nenhum vídeo recebeu uma marca falsa de revisão integral. Nenhuma nova versão foi publicada em produção. A primeira inspeção desktop conferiu a home e os filtros da biblioteca; as larguras e todos os estados do contrato ainda precisam de comparação pareada.</p><p><a href="execucao-corretiva.json">Manifesto de execução e pendências</a> · <a href="auditoria-execucao-atual.json">Auditoria do acervo e dos critérios de liberação</a>.</p><p>Arquivos completos: <a href="quantidades-original-pesquisadas.json">inventário quantitativo</a> · <a href="../../curadoria/business/pesquisa-artigos-corretivo.json">pesquisa de artigos</a> · <a href="../../curadoria/business/pesquisa-videos-literatura-corretivo.json">pesquisa de vídeos e literatura</a>.</p></section></main><footer>Harpya · Relatório corretivo fundamentado no código e nos registros primários citados. Os catálogos de pesquisa conservam métodos, limites e pendências. Data da auditoria: 06/11/2026.</footer><script>const input=document.querySelector('#busca');const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();input.addEventListener('input',()=>{{const terms=norm(input.value).split(/\s+/).filter(Boolean);let n=0;for(const c of document.querySelectorAll('.candidate')){{c.hidden=!terms.every(t=>norm(c.textContent).includes(t));if(!c.hidden)n++}}document.querySelector('#contador').textContent=n+' fichas'}});</script></body></html>'''
(p/'docs/corretivo/pesquisa-quantidades-e-acervo.html').write_text(report)
print('Relatório HTML:',len(report),'caracteres; artigos',len(a['itens']),'vídeos',len(v['videos']),'livros',len(v['literatura']),'novos artigos',len(novos))
